package com.hireflow.api.saved; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/saved-jobs") public class SavedJobController {private final SavedJobRepository r; public SavedJobController(SavedJobRepository x){r=x;} @GetMapping public List<SavedJob> mine(@RequestHeader("X-User-Email")String e){return r.findByEmail(e);} @PostMapping("/{jobId}") public ResponseEntity<?> save(@PathVariable Long jobId,@RequestHeader("X-User-Email")String e){if(r.findByJobIdAndEmail(jobId,e).isPresent())return ResponseEntity.status(409).body(Map.of("message","Already saved"));SavedJob s=new SavedJob();s.setJobId(jobId);s.setEmail(e);return ResponseEntity.status(201).body(r.save(s));} @DeleteMapping("/{jobId}") public void remove(@PathVariable Long jobId,@RequestHeader("X-User-Email")String e){r.findByJobIdAndEmail(jobId,e).ifPresent(s->r.delete(s));}}